"""The personal context block and a pending change to its target (spec 006)."""

from dataclasses import dataclass
from pathlib import Path
from typing import Final

from opscout.core.config import MARKER_TEXT

BEGIN: Final = f"<!-- {MARKER_TEXT}:begin -->"
END: Final = f"<!-- {MARKER_TEXT}:end -->"
NOTE: Final = (
    "<!-- Generated by opscout from your configuration: edit the configuration, then run "
    "opscout context apply. -->"
)

MAX_TARGET_BYTES: Final = 1024 * 1024
"""A target above this size is not read or written."""

TARGET_NAME: Final = "CLAUDE.md"
"""The user's instructions file in Claude Code's configuration directory."""


class SpliceError(Exception):
    """The block cannot be put into the target's text with certainty."""


class MarkerError(SpliceError):
    """The target's markers cannot be read with certainty; the message names the line."""


@dataclass(frozen=True)
class PendingChange:
    """A target's current content, its new content and the code that confirms the change."""

    target: Path
    current: bytes | None
    new: bytes
    code: str

    @property
    def changed(self) -> bool:
        """Return True when applying would change the target."""
        return self.new != self.current
